let panStart=null,didPan=false,homeView='stack';
const $=id=>document.getElementById(id),scene=$('scene'),dialog=$('engineering'),theme=initTheme();let frames=[],engineering,resources,relationships,index=-1,ready=false,coverage;
const graphNavigation=installGraphNavigation({scene,overview:$('overview'),map:$('overview-map'),zoomIn:$('zoom-in'),zoomOut:$('zoom-out'),fit:$('zoom-fit'),readout:$('zoom-level'),onGesture:()=>{didPan=true;}});
function themeLabel(){$('theme-toggle').textContent='Theme: '+theme.preference[0].toUpperCase()+theme.preference.slice(1);}themeLabel();$('theme-toggle').onclick=()=>{const values=['system','light','dark'];theme.setPreference(values[(values.indexOf(theme.preference)+1)%3]);themeLabel();};
export function validateFrames(frames,resources,relationships){if(!Array.isArray(frames)||frames.length!==7)throw Error('Use seven operating-model stages');for(const [i,f]of frames.entries()){if(!f.title||!f.caption||!f.example?.body||!f.worksNow||!f.delegatedResponsibility||!f.stateArtifact||!f.remainingLimitation||f.added?.length!==1||f.added[0]!==capabilities[i].id)throw Error('Incomplete cumulative operating model');for(const id of f.protocols){const e=relationships.get(id);if(!e||!capabilities.slice(0,i+1).flatMap(c=>c.resources).includes(e.source)||!capabilities.slice(0,i+1).flatMap(c=>c.resources).includes(e.target))throw Error('A stage cannot use a future communication endpoint');}}return frames;}
function render(){
 const current=index<0&&homeView==='current';
 scene.innerHTML=current?currentArchitectureGraphic():capabilityGraphic(index,coverage,innerWidth<700);
 const f=frames[Math.max(0,index)];
 $('title').textContent=current?currentArchitecture.title:index<0?'The stack, from the ground up.':f.title;
 $('caption').textContent=current?currentArchitecture.summary:index<0?'Start with compute to run your code and GitHub to share and review it. Add AI coding, LangGraph memory, Sokolovski coordination and Windmill jobs as you build up the stack.':f.caption;
 $('view-status').textContent=current?'Component flow · Ownership split under review':index<0?'Foundational stack · Full map shows the complete design':'Building the end-state design · Select Full map to see it together';
 $('back').disabled=index===-1;$('next').disabled=false;$('next').setAttribute?.('aria-label',index===6?'Open full map':'Next scene');$('next').title=index===6?'Full map':'Next chapter';document.body.dataset.scene=index;document.body.dataset.view=current?'current':index<0?'stack':'stage';
 $('current-map').setAttribute?.('aria-pressed',String(current));$('stack-view').setAttribute?.('aria-pressed',String(index<0&&!current));
 for(const [i,b] of [...$('capabilities').children].entries()){b.classList.toggle('active',i===index);b.setAttribute?.('aria-current',i===index?'step':'false');}
 scene.scrollTop=0;scene.scrollLeft=0;
 if(current){graphNavigation.reset(0,{overviewGraphic:currentArchitectureSvg,initialScale:innerWidth<700 ? .25 : .5,centerContent:true});}
 else graphNavigation.reset(index,{fitAdded:index>=0});
}
$('current-map').onclick=()=>{if(!ready||dialog.open)return;index=-1;homeView='current';render();};
$('stack-view').onclick=()=>{if(!ready||dialog.open)return;index=-1;homeView='stack';render();};
function move(n){if(!ready||dialog.open)return;if(n>0&&index===frames.length-1){index=-1;homeView='current';}else index=Math.max(-1,Math.min(frames.length-1,index+n));render();}
$('back').onclick=()=>move(-1);$('next').onclick=()=>move(1);
function el(tag,value,cls){const e=document.createElement(tag);if(value)e.textContent=value;if(cls)e.className=cls;return e;}
function list(items){const ul=el('ul');for(const value of items)ul.append(el('li',value));return ul;}
function context(root,stage=index<0?6:index){const f=frames[stage];root.append(el('h3','What this solves'),el('p',f.pain),el('h3','How it helps'),el('p',f.worksNow),el('h3','How the tools work together'),el('p',f.delegatedResponsibility),el('h3','What you can look back at'),el('p',f.stateArtifact),el('h3','What still needs your attention'),el('p',f.remainingLimitation));const example=el('details');example.append(el('summary','For example: '+f.example.title),el('p',f.example.body));root.append(example,el('p','These stages explain how the design builds up. Open Full map to see how all the layers connect in the complete end-state design.','scope'));}
function edgeDetail(edge){const box=el('section'),source=resources.get(edge.source),target=resources.get(edge.target);box.append(el('p',`${source.name} → ${target.name}`),el('span',edge.protocol==='No label in source'?'Transport unspecified in source':edge.protocol,'protocol-label'),el('h3','What is shared'),el('p',edge.payload),el('h3','Why it matters'),el('p',edge.purpose),el('small','First available with stage '+(coverage.relationships.find(x=>x.id===edge.id).stage+1)));box.append(el('h3','Design context'),el('p',edge.evidenceStatus??'Retained architecture relationship; live availability not verified.'),el('h3','Rules and recovery'),list([...(edge.contractNotes??[]),...(edge.recoveryNotes??[])]));return box;}
function resourceDetail(r){const box=el('section');box.append(el('p',r.activity+(r.group?' · '+r.group:'')),el('small','Operating-model stage '+(coverage.resources.find(x=>x.id===r.id).stage+1)),list(r.bullets??[]),el('h3','Rules and recovery'),list([...(r.contractNotes??[]),...(r.recoveryNotes??[])]),el('h3','Connected tools'));for(const e of relationships.values())if(e.source===r.id||e.target===r.id){const d=el('details');d.append(el('summary',`${resources.get(e.source).name} → ${resources.get(e.target).name}`),edgeDetail(e));box.append(d);}return box;}
const responsibilitySummary=[
 'Linear defines outcomes, dependencies and acceptance criteria. It gives AI work a clear scope and a shared definition of done.',
 'Sokolovski coordinates the AI coding effort. It turns eligible work into scoped assignments for coding workers and admits them against shared capacity.',
 'LangGraph carries workflow progress between stages. Its decisions and checkpoints let the design resume, retry or recover with the context of earlier results.',
 'Windmill provides bounded execution. It runs validation and integration jobs on the resulting work and retains evidence for the next decision, within the installed edition’s limits.',
 'GitHub holds the source and reviewed changes. AI output becomes a reviewable candidate, with independent review and validation before accepted integration or a separately qualified release.'
];
$('portfolio-projects').onclick=()=>showDetail('projects');
$('responsibilities').onclick=()=>showDetail('responsibilities');
function showDetail(kind,id){if(!ready)return;const root=$('detail-content');if(kind==='projects'){root.replaceChildren(el('h2','Selected projects'));for(const [name,description] of [['offmenu','Food inventory, recipes and meal planning.'],['colour-index-compression','Experimental lossless compression research.'],['usf-v3','Evidence-driven AI software delivery.'],['anqr-v3','ANQR product capabilities and conformance tests.'],['anqr','Archived QR generation and analysis monorepo.'],['anqr-i18n','Community translations for ANQR.'],['lixit','Archived lending submission prototype.']]){const a=el('a',name);a.href='https://github.com/maldous/'+name;a.target='_blank';a.rel='noopener noreferrer';const p=el('p');p.append(a,document.createTextNode(' — '+description));root.append(p);}dialog.showModal();dialog.scrollTop=0;return;}if(kind==='current-node'||kind==='current-edge'){
 const value=(kind==='current-node'?currentArchitecture.nodes:currentArchitecture.edges).find(x=>x.id===id);if(!value)return;
 root.replaceChildren(el('h2',value.name??value.label));root.append(el('p',value.purpose??(currentArchitecture.nodes.find(n=>n.id===value.source).name+' → '+currentArchitecture.nodes.find(n=>n.id===value.target).name)),el('p',value.detail));
 if(value.status)root.append(el('p',value.status,'protocol-label'));
 if(currentArchitecture.designNote)root.append(el('h3','Design status'),el('p',currentArchitecture.designNote));
 dialog.showModal();dialog.scrollTop=0;return;
 }if(kind==='responsibilities'){root.replaceChildren(el('h2','AI high-level design'),el('p','In my AI-assisted delivery designs, these five components connect the intent of a task to a reviewed, evidenced result.'));for(const statement of responsibilitySummary)root.append(el('p',statement));if(currentArchitecture.designNote)root.append(el('h3','Design status'),el('p',currentArchitecture.designNote));root.append(el('p','Together, Linear establishes what to achieve, Sokolovski coordinates who works on it, LangGraph carries progress, Windmill supplies execution evidence, and GitHub records the reviewed result. Feedback and failed checks return work for correction before it advances.'));dialog.showModal();dialog.scrollTop=0;return;}let contextStage=index<0?6:index;root.replaceChildren();if(kind==='capability'){const i=capabilities.findIndex(c=>c.id===id),c=capabilities[i];contextStage=i;root.append(el('h2',c.title),el('h3','The tools in this layer'));for(const rid of c.resources){const r=resources.get(rid),d=el('details');d.append(el('summary',r.name),resourceDetail(r));root.append(d);}root.append(el('h3','How this layer connects'));for(const item of coverage.relationships.filter(x=>x.stage===i)){const e=relationships.get(item.id),d=el('details');d.append(el('summary',`${resources.get(e.source).name} → ${resources.get(e.target).name} · ${e.protocol}`),edgeDetail(e));root.append(d);}}else if(kind==='actor'){const r=resources.get(id);root.append(el('h2',r.name),resourceDetail(r));}else if(kind==='handoff'){const e=relationships.get(id);root.append(el('h2','Tool connection'),edgeDetail(e));}else{root.append(el('h2',id),el('p','Activity grouping for explanation, not a deployment boundary.'));for(const r of resources.values())if(r.activity===id){const d=el('details');d.append(el('summary',r.name),resourceDetail(r));root.append(d);}}context(root,contextStage);dialog.showModal();dialog.scrollTop=0;}
$('close-detail').onclick=()=>dialog.close();dialog.onclick=e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}};
scene.onpointerdown=e=>{panStart=[e.clientX,e.clientY];didPan=false;};
scene.onpointermove=e=>{if(panStart&&Math.hypot(e.clientX-panStart[0],e.clientY-panStart[1])>8)didPan=true;};
scene.onpointercancel=()=>{panStart=null;didPan=true;};
scene.onpointerup=()=>{panStart=null;};
scene.onclick=e=>{if(didPan){didPan=false;return;}const node=e.target.closest('[data-current-node]'),edge=e.target.closest('[data-current-edge]');if(node||edge)return showDetail(node?'current-node':'current-edge',node?.dataset.currentNode??edge.dataset.currentEdge);const stage=e.target.closest('[data-stage]');if(stage){index=Number(stage.dataset.stage);render();return;}const cap=e.target.closest('[data-capability]'),actor=e.target.closest('[data-actor]'),handoff=e.target.closest('[data-handoff]');if(cap)return showDetail('capability',cap.dataset.capability);if(actor)return showDetail('actor',actor.dataset.actor);if(handoff)return showDetail('handoff',handoff.dataset.handoff);if(index<0&&homeView==='current')return;if(!getSelection()?.toString())move(e.clientX<innerWidth/2?-1:1);};
addEventListener('keydown',e=>{if(dialog.open||e.target.closest('button,summary,input,select,textarea'))return;const node=e.target.closest('[data-current-node]'),edge=e.target.closest('[data-current-edge]');if((node||edge)&&['Enter',' '].includes(e.key)){e.preventDefault();showDetail(node?'current-node':'current-edge',node?.dataset.currentNode??edge.dataset.currentEdge);return;}const jump=e.target.closest('[data-stage]');if(jump&&(e.key==='Enter'||e.key===' ')){e.preventDefault();index=Number(jump.dataset.stage);render();return;}const cap=e.target.closest('[data-capability]'),actor=e.target.closest('[data-actor]'),handoff=e.target.closest('[data-handoff]');if((e.key==='Enter'||e.key===' ')&&(cap||actor||handoff)){e.preventDefault();showDetail(cap?'capability':actor?'actor':'handoff',cap?.dataset.capability||actor?.dataset.actor||handoff.dataset.handoff);return;}if(['ArrowLeft','ArrowRight',' ','Home','End'].includes(e.key))e.preventDefault();if(e.key==='ArrowLeft')move(-1);if(e.key==='ArrowRight'||e.key===' ')move(1);if(ready&&['Home','End'].includes(e.key)){index=e.key==='Home'?-1:frames.length-1;if(e.key==='Home')homeView='stack';render();}});
let compact=innerWidth<700;addEventListener('resize',()=>{if(ready&&(innerWidth<700)!==compact){compact=innerWidth<700;render();}});
try{const [data,catalog]=await Promise.all(['operating-model.json?v=41-tools-mobile-zoom','engineering.json?v=41-tools-mobile-zoom'].map(p=>fetch(p).then(r=>{if(!r.ok)throw Error('Story asset unavailable');return r.json();})));engineering=catalog;resources=new Map(catalog.resources.map(r=>[r.id,r]));relationships=new Map(catalog.relationships.map(r=>[r.id,r]));coverage=buildCoverage(catalog);frames=validateFrames(data,resources,relationships);for(const [i,c] of capabilities.entries()){const b=el('button',c.title);b.onclick=()=>{if(!dialog.open){index=i;render();}};$('capabilities').append(b);}await document.fonts.ready;ready=true;render();}catch(e){$('loading').textContent='Could not load the story. '+e.message;}
